<?php if($path==='/classificacao' && !empty($g['starting'])): ?><article class="panel"><h2>Seu campeonato começa com um clube</h2><a href="/carreira">Continuar início da carreira →</a></article><?php elseif($path==='/classificacao' && !empty($g['official'])): CompetitionView::standings($g); elseif($path==='/classificacao'): ?><h2>Classificação</h2><div class="table-responsive"><table class="table"><thead><tr><th>Clube fictício</th><th>PTS</th><th>J</th><th>V</th><th>E</th><th>D</th><th>GP</th><th>GC</th><th>SG</th></tr></thead><tbody><?php foreach(Schedule::table($g['matches'],$g['teams']) as $i=>$t): ?><tr><td><?=e(($i+1).'. '.$t['team'])?><?=$t['team']===$g['club']?' ★':''?></td><?php foreach(['points','played','wins','draws','losses','gf','ga','gd'] as $k): ?><td><?=e($t[$k])?></td><?php endforeach ?></tr><?php endforeach ?></tbody></table></div><h2>Resultados e calendário</h2><div class="grid"><?php foreach($g['matches'] as $match): ?><div class="panel"><small>Rodada <?=e($match['round'])?></small><p><?=e($match['home'])?><br><b><?= $match['status']==='finalizada'?e($match['hg'].' × '.$match['ag']):'×'?></b><br><?=e($match['away'])?></p></div><?php endforeach ?></div>
