<?php elseif(in_array($g['stage'],['resumo','oferta','competicao_resumo'],true)): ?><article class="panel transfer-panel"><p class="tag">TEMPORADA CONCLUÍDA</p><?php if($g['stage']==='resumo'): ?><h2>Qual será seu próximo clube?</h2><p><?=e(Presentation::seasonStory($g))?></p><p>Continuar em <?=e(ClubBadge::name($g['club']))?> ou buscar espaço em outro clube? Descubra quem quer contar com você.</p><?php form('/transferencia/roleta',$g); ?><button class="btn btn-primary btn-lg">Ver minha proposta →</button></form><?php else: ?><h2>Seu próximo passo</h2><?php $chosen=current(array_filter($g['offers'],fn($offer)=>$offer['selected'])); Wheel::render($g['offers'],$chosen['club'],'offer:'.$g['id'].':'.$g['season']); ?><div class="transfer-actions"><?php TransferMarket::describe($chosen); ?><p><?=e($chosen['club'])?> quer você no elenco. Aceitar a proposta ou continuar em <?=e(ClubBadge::name($g['club']))?>?</p><?php form('/transferencia/responder',$g); ?><button class="btn btn-primary" name="accept" value="yes">Aceitar proposta</button><button class="btn btn-outline-light" name="accept" value="no">Ficar no meu clube</button></form></div><?php endif ?></article><details class="panel season-recap"><summary>Ver minha temporada</summary><?php PlayMode::report($g); ?><p><?=e(Presentation::seasonStory($g))?></p><p>Nota média: <?=e($summary['average'])?></p><a href="/classificacao">Classificação final →</a><?php Presentation::goalHistory($g); ?></details>
<?php elseif($g['stage']==='partida'): Presentation::score($g,$m); ?>
<?php if($m['status']!=='em_andamento' || $m['minute']<$m['entry'] || $m['minute']>=$m['exit']): form('/partida/avancar',$g); ?><button class="btn btn-primary btn-lg">Avançar <?= $m['status']==='intervalo'?'para o segundo tempo':'a partida'?> →</button></form><?php else: $situation=Game::situation($g);$clearChance=!empty($situation['clear_chance']); ?><article class="panel"><h2><?=e($situation['text']??'O adversário se aproxima. O que você faz?')?></h2><p class="chance-caption"><?= $clearChance?'Nesta chance clara, sucesso significa gol ou assistência.':'No chute, sucesso é gol. Nas outras ações, sucesso permite continuar a jogada.' ?></p><?php form('/partida/decidir',$g); foreach(Game::choices($g) as $i=>$o): $chance=Game::chance($g,$o); $percent=number_format($chance,2,',','');$outcome=$clearChance?($o['action']==='passe'?'assistência':'gol'):($o['action']==='chute'?'gol':'sucesso'); ?><button class="choice" name="option" value="<?=e($i)?>"><b><?=e(chr(65+$i))?></b><span class="choice-text"><?=e($o['text'])?></span><span class="choice-chance chance-<?= $chance>=65?'high':($chance>=40?'medium':'low') ?>" aria-label="Chance de <?=e($outcome)?>: <?=e($percent)?>%"><strong><?=e($percent)?>%</strong><small><?=e($outcome)?></small></span></button><?php endforeach ?></form></article><?php endif ?>
<?php else: $s=Game::situation($g); ?><?php if($g['stage']==='fim_semana'): ?><article class="panel post-match"><p class="tag">APITO FINAL</p><h2><?=e($m['home'].' '.$m['hg'].' × '.$m['ag'].' '.$m['away'])?></h2><p>Você: <?=e($m['stats']['goals'])?> gols · <?=e($m['stats']['assists'])?> assistências</p></article><?php endif ?><article class="panel"><p class="tag"><?=e(str_replace('_',' ',strtoupper($g['stage'])))?></p><h2><?=e($s['text'])?></h2><p>O que você faz?</p><?php form('/decisao/registrar',$g); foreach(Game::choices($g) as $i=>$o): ?><button class="choice" name="option" value="<?=e($i)?>"><b><?=e(chr(65+$i))?></b><span><?=e($o['text'])?></span></button><?php endforeach ?></form></article>
<?php if($g['stage']==='fim_semana'): ?><details class="panel season-recap"><summary>Ver resumo da partida e meus gols</summary><?php Presentation::matchStats($g,$m); Presentation::goalHistory($g); Presentation::radio($m); ?><a href="/classificacao">Resultados e tabela →</a></details><?php endif ?><?php endif ?><?php if(!in_array($g['stage'],['handicap','clube_inicio','partida','fim_semana','resumo','oferta','competicao_resumo'],true)) Presentation::goalHistory($g); ?></section><aside class="career-extras"><a class="profile-entry panel" href="/jogador"><span>MEU JOGADOR</span><strong>Habilidades e evolução ↗</strong><small>Condição física, desempenho e reputação</small></a><details class="panel"><summary>Temporadas anteriores</summary><?php foreach($g['history'] as $h): ?><p>Temporada <?=e($h['season'])?> · <?=e($h['club'])?> · <?=e($h['goals'])?> gols · nota <?=e($h['average'])?></p><?php endforeach ?><?php if(!$g['history']): ?><p>Seu primeiro capítulo está em construção.</p><?php endif ?></details><details class="panel"><summary>Minha carreira</summary><p><a href="/carreira/nova">Começar nova carreira</a> · <a href="/carreiras">Gerenciar carreiras</a></p><p><a href="/carreira/arquivadas">Retomar carreira arquivada</a></p></details></aside></div><?php endif ?><?php endif ?>
</main><footer><strong>Rumo à Camisa 10</strong><br>Sua carreira. Suas escolhas. Seu futebol.</footer></body></html>
